WITH with_last AS (SELECT s.*, top1.txn_type, top1.transaction_amount FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_type, c.amount AS transaction_amount FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, customer_id, account_type, balance, opened_date, status, CASE WHEN status RLIKE '^(CLOSED|FROZEN)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS status_zone FROM with_last ORDER BY status_zone DESC NULLS FIRST;
